import re
def boolean_flags(s):
 d={}
 for r in s.split(','):
  p=r.split('=')
  if len(p)!=2 or not re.fullmatch(r'[a-z][a-z0-9]*(?:-[a-z0-9]+)*',p[0]) or p[1] not in ('true','false') or p[0] in d:return None
  d[p[0]]=p[1]=='true'
 return ','.join(sorted(k for k,v in d.items() if v)) if d else None
